const msg = $input.first().json?.message || $input.first().json?.channel_post || {};
const chatId  = String(msg?.chat?.id || '');
const doc     = msg?.document || null;
const caption = msg?.caption || '';

if (!doc) {
  return [{ json: { ignorar: true, motivo: 'Mensagem sem documento', chatId } }];
}
if (!(doc.mime_type || '').includes('pdf')) {
  return [{ json: { ignorar: true, motivo: 'Arquivo não é PDF — envie o arquivo .pdf da fatura', chatId } }];
}

const mMap = {
  'janeiro':'Janeiro','fevereiro':'Fevereiro','março':'Março','marco':'Março',
  'abril':'Abril','maio':'Maio','junho':'Junho','julho':'Julho',
  'agosto':'Agosto','setembro':'Setembro','outubro':'Outubro',
  'novembro':'Novembro','dezembro':'Dezembro'
};
const mesCaption = Object.entries(mMap).find(([k]) => caption.toLowerCase().includes(k))?.[1] || '';

return [{ json: { ignorar: false, fileId: doc.file_id, fileName: doc.file_name || 'fatura.pdf', chatId, mesCaption, caption } }];

const filePath = $input.first().json.result?.file_path || '';
if (!filePath) throw new Error('file_path não retornado. Verifique o file_id.');
const doc = $('Extrair Documento').first().json;
return [{ json: { ...doc, filePath } }];

const texto      = $input.first().json.text || '';
const chatId     = $('Extrair Documento').first().json.chatId;
const mesCaption = $('Extrair Documento').first().json.mesCaption || '';

const prompt = `Você é especialista em faturas bancárias brasileiras.

Analise a fatura e extraia TODOS os lançamentos. Identifique o banco/cartão de origem.

Retorne SOMENTE JSON puro (sem markdown):
{
  "mes": "NomeDoMes",
  "banco": "NomeExatoDoBancoOuCartao",
  "total_despesas": 0.00,
  "total_receitas": 0.00,
  "lancamentos": [
    {
      "data": "DD/MM/AAAA",
      "descricao": "Nome limpo max 50 chars",
      "categoria": "Alimentação|Moradia|Transporte|Saúde|Educação|Lazer|Vestuário|Assinaturas|Investimentos|Outros",
      "tipo": "Despesa|Receita",
      "valor": 0.00,
      "forma_pagamento": "Crédito|Débito|Pix|Dinheiro|Boleto|Transferência",
      "cartao": "NomeExatoDoBanco",
      "parcelas": 1,
      "observacoes": ""
    }
  ]
}

Regras: ignore total, pagamento mínimo, saldo anterior, encargos, IOF. Estornos = Receita. campo cartao = mesmo valor de banco.

Texto da fatura:
${texto}`;

return [{ json: { model: 'claude-opus-4-6', max_tokens: 8000, messages: [{ role: 'user', content: prompt }], _chatId: chatId, _mesCaption: mesCaption } }];

const resposta   = $input.first().json.content?.[0]?.text || '';
const chatId     = $('Montar Prompt').first().json._chatId;
const mesCaption = $('Montar Prompt').first().json._mesCaption;

const mMap = {
  'janeiro':'Janeiro','fevereiro':'Fevereiro','março':'Março','marco':'Março',
  'abril':'Abril','maio':'Maio','junho':'Junho','julho':'Julho',
  'agosto':'Agosto','setembro':'Setembro','outubro':'Outubro',
  'novembro':'Novembro','dezembro':'Dezembro'
};

let dados;
try {
  const m = resposta.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('JSON não encontrado');
  dados = JSON.parse(m[0]);
} catch(e) {
  return [{ json: { erro: true, msg: e.message, chatId, lancamentos: [], mes: 'Erro', banco: 'Erro' } }];
}

const mes   = mesCaption || mMap[(dados.mes||'').toLowerCase().trim()] || dados.mes || 'Indefinido';
const banco = dados.banco || 'N/A';

const lancamentos = (dados.lancamentos||[]).map(l => ({
  mes, banco,
  data:            l.data||'',
  descricao:       (l.descricao||'').substring(0,50),
  categoria:       l.categoria||'Outros',
  tipo:            l.tipo||'Despesa',
  valor:           parseFloat(l.valor)||0,
  forma_pagamento: l.forma_pagamento||'',
  cartao:          l.cartao||banco,
  parcelas:        parseInt(l.parcelas)||1,
  observacoes:     l.observacoes||''
}));

const tot_desp = lancamentos.filter(l=>l.tipo==='Despesa').reduce((s,l)=>s+l.valor,0);
const tot_rec  = lancamentos.filter(l=>l.tipo==='Receita').reduce((s,l)=>s+l.valor,0);

const por_cat = {};
lancamentos.forEach(l => { if(l.tipo==='Despesa') por_cat[l.categoria]=(por_cat[l.categoria]||0)+l.valor; });
const top_cat = Object.entries(por_cat).sort((a,b)=>b[1]-a[1]).slice(0,3);

const resumo = `✅ *Fatura processada com sucesso\!*\n\n🏦 *${banco}* — ${mes}\n📋 ${lancamentos.length} lançamentos encontrados\n\n💸 Despesas: R\$ ${tot_desp.toFixed(2).replace('.',',')}\n💰 Receitas: R\$ ${tot_rec.toFixed(2).replace('.',',')}\n📊 Saldo: R\$ ${(tot_rec-tot_desp).toFixed(2).replace('.',',')}\n\n🔝 *Top categorias:*\n${top_cat.map(([c,v])=>`  • ${c}: R\$ ${v.toFixed(2).replace('.',',')}`).join('\n')}\n\n_Lançamentos salvos no Google Sheets ✓_\n_Verificando orçamentos\.\.\._`;

return [{ json: { mes, banco, lancamentos, tot_desp, tot_rec, chatId, resumo, qtd: lancamentos.length } }];
